      "slice",
      "result"
    ],
    "abstraction_levels": [
      "scope",
      "slice_component"
    ],
    "process_fit_signals": [
      "high_ambiguity_component_work",
      "large_component_design_needed",
      "cross_cutting_decisions_needed",
      "subagent_driven_implementation_needed",
      "deploy_or_live_validation_may_be_needed"
    ],
    "disallowed_when": [
      "small_tdd_patch_fits_lightweight_variant",
      "unknown_truth_requires_debug_root_cause_first",
      "request_is_pure_operation_without_code_or_design_work",
      "request_is_durable_domain_write_only",
      "authority_for_execution_is_missing_and_user_requests_execution_now"
    ]
  },
