    "required_inputs": [
      "parent_scope_candidate",
      "slice_parent_variant_integration",
      "pipeline_variant_selection_record",
      "kernel_assessment",
      "authority_state",
      "freshness_state",
      "full_variant_artifact_contract"
    ],
    "required_evidence": [
      "scope_baseline",
      "component_boundary",
      "current_workspace_state_or_declared_unknown",
      "source_provenance",
      "artifact_contract_ref"
    ],
    "freshness_requirements": [
      "refresh repo/workspace truth before current-state claims",
      "separate historical clues from current baseline",
      "record stale evidence as stale before design decisions"
    ],
    "authority_required": [
      "read_workspace",
      "propose_slice_source_change",
      "execute_plan_when_authorized",
      "request_deploy_validation_when_required"
    ],
    "approval_triggers": [
      "source_mutation",
      "worktree_creation_or_cleanup",
      "deployment_or_live_validation_required",
      "canonical_slice_write",
      "promotion_candidate"
    ]
  },
